#!/usr/bin/env node
// software-factory [folder] [--port <port>] [--no-open]
// software-factory new <name>
// software-factory card … (the board's cards, for planning in a coding agent)
// software-factory prototype … (a card's prototype, in its own copy of the code)
// software-factory upgrade (the project's factory, to this core's version)
// software-factory check (the records' checks) · check-docs (the knowledge
// base's checks) · help
//
// Run in a project, starts its factory on this computer and opens it in the
// browser. The factory lives in the project, in its factory/ folder, found
// from anywhere inside it. Where there is none yet, the browser sets one up
// with the owner: the coach reads the project's code (the top of its git
// repository, or the folder) and drafts the factory on a canvas. `new`
// makes a folder for a new idea and sets it up there.
//
// Node says that its SQLite (node:sqlite, where the records live) is
// experimental each time the command starts; that one warning is kept
// quiet before anything else loads, then the command runs (command.ts).
import { quietSqliteWarning } from "../src/quiet-sqlite.js";
quietSqliteWarning();
await import("./command.js");
